import React, { useState, useEffect } from "react";
import axios from "axios";

const CreateSchedule = () => {
    const [subject, setSubject] = useState("");
    const [teacher, setTeacher] = useState("");
    const [period, setPeriod] = useState("");
    const [group, setGroup] = useState("");
    const [lessonType, setLessonType] = useState("");
    const [dayOfWeek, setDayOfWeek] = useState(""); // ✅ День недели
    const [room, setRoom] = useState(""); // ✅ Кабинет
    const [periods, setPeriods] = useState([]);
    const [rooms, setRooms] = useState([]);

    const weekDays = [
        { id: 1, name: "Понедельник" },
        { id: 2, name: "Вторник" },
        { id: 3, name: "Среда" },
        { id: 4, name: "Четверг" },
        { id: 5, name: "Пятница" },
        { id: 6, name: "Суббота" },
        { id: 7, name: "Воскресенье" }
    ];

    useEffect(() => {
        const fetchData = async () => {
            try {
                const token = localStorage.getItem("token");
                const [periodsResponse, roomsResponse, groupsResponse] = await Promise.all([
                    axios.get("/api/periods", { headers: { Authorization: `Bearer ${token}` } }),
                    axios.get("/api/rooms", { headers: { Authorization: `Bearer ${token}` } }),
                    axios.get("/groups", { headers: { Authorization: `Bearer ${token}` } })
                ]);
                setPeriods(periodsResponse.data);
                setRooms(roomsResponse.data);
                setGroups(groupsResponse.data);
            } catch (error) {
                console.error("Ошибка загрузки данных:", error);
            }
        };

        fetchData();
    }, []);

    const handleCreateSchedule = async (e) => {
        e.preventDefault();
        try {
            const token = localStorage.getItem("token");
            await axios.post("/schedule", { subject, teacher, period, lessonType, group, dayOfWeek, room }, {
                headers: { Authorization: `Bearer ${token}` }
            });

            setSubject("");
            setTeacher("");
            setPeriod("");
            setLessonType("");
            setGroup("");
            setDayOfWeek("");
            setRoom("");
        } catch (error) {
            console.error("Ошибка при добавлении пары", error);
        }
    };

    return (
        <div>
            <h2>Добавить пару</h2>
            <form onSubmit={handleCreateSchedule}>
                <input type="text" placeholder="Название предмета" value={subject} onChange={(e) => setSubject(e.target.value)} required />
                <input type="text" placeholder="Преподаватель" value={teacher} onChange={(e) => setTeacher(e.target.value)} required />

                {/* Выбор дня недели */}
                <select value={dayOfWeek} onChange={(e) => setDayOfWeek(e.target.value)} required>
                    <option value="">Выберите день недели</option>
                    {weekDays.map(day => (
                        <option key={day.id} value={day.id}>{day.name}</option>
                    ))}
                </select>

                {/* Выбор времени пары */}
                <select value={period} onChange={(e) => setPeriod(e.target.value)} required>
                    <option value="">Выберите время пары</option>
                    {periods.map(period => (
                        <option key={period._id} value={period._id}>
                            {period.name}: {period.startTime} - {period.endTime}
                        </option>
                    ))}
                </select>

                {/* Выбор кабинета */}
                <select value={room} onChange={(e) => setRoom(e.target.value)} required>
                    <option value="">Выберите кабинет</option>
                    {rooms.map(room => (
                        <option key={room._id} value={room._id}>{room.name}</option>
                    ))}
                </select>

                <button type="submit">Добавить</button>
            </form>
        </div>
    );
};

export default CreateSchedule;
